def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    parts = s.split('.')
    result = []
    for part in parts:
        # Remove any non-digit characters from the end
        part = part.rstrip('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ')
        # Remove any non-digit characters from the beginning
        part = part.lstrip('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ')
        # If the part is empty or not a valid integer, skip it
        if part.isdigit():
            result.append(int(part))
        else:
            # Try to extract leading digits
            digits = ''
            for char in part:
                if char.isdigit():
                    digits += char
                else:
                    break
            if digits:
                result.append(int(digits))
    return tuple(result)
