def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Remove duplicates while preserving order
    seen = set()
    unique_classes = []
    for cls in classes:
        if cls not in seen:
            seen.add(cls)
            unique_classes.append(cls)

    # Remove any class that is a subclass of another class in the list
    minimal = []
    for i, cls in enumerate(unique_classes):
        is_redundant = False
        for j, other in enumerate(unique_classes):
            if i != j and issubclass(cls, other):
                is_redundant = True
                break
        if not is_redundant:
            minimal.append(cls)

    return minimal
