def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Check that prior is an instance of InventoryValidator
    if not isinstance(prior, type(self)):
        raise TypeError("prior must be an instance of the same class as self")

    # Check that prior's version is less than or equal to self's version
    if prior.version > self.version:
        raise ValueError("prior version must be less than or equal to current version")

    # Check that all items in prior are present in self
    for item in prior.items:
        if item not in self.items:
            raise ValueError(f"Item {item} in prior version is not present in current version")

    # Check that the quantities in prior are less than or equal to those in self
    for item, prior_qty in prior.items.items():
        if item in self.items:
            if prior_qty > self.items[item]:
                raise ValueError(f"Quantity of item {item} in prior version is greater than in current version")

    # If all checks pass, return True
    return True
