    num_objects = 0
    good_objects = 0

    # Iterate through the hierarchy and validate each object
    for obj in self.hierarchy:
        num_objects += 1
        if validate_objects:
            if obj.validate():
                good_objects += 1
            else:
                if show_warnings:
                    print(f"Warning: Object {obj} failed validation")
        else:
            good_objects += 1

        if check_digests:
            if obj.check_digest():
                pass
            else:
                if show_warnings:
                    print(f"Warning: Object {obj} failed digest check")

