def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:

    """
    if not image_href:
        raise ValueError("image_href cannot be empty")

    # Check if the href starts with http:// or https://
    if image_href.startswith("http://"):
        use_ssl = False
        rest = image_href[len("http://"):]
    elif image_href.startswith("https://"):
        use_ssl = True
        rest = image_href[len("https://"):]
    else:
        raise ValueError("image_href must start with http:// or https://")

    # Split the rest into netloc and path
    if "/" in rest:
        netloc, path = rest.split("/", 1)
    else:
        netloc = rest
        path = ""

    # The image_id is the last part of the path
    if path:
        image_id = path.split("/")[-1]
    else:
        image_id = ""

    return (image_id, netloc, use_ssl)
