def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, str):
        commands = [commands]
    if isinstance(args, str):
        args = [args]
    if not isinstance(args, list):
        args = [args]
    full_command = commands + args
    if verbose:
        print("Running command: " + " ".join(full_command))
    try:
        if hide_stderr:
            result = subprocess.run(full_command, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, check=True)
        else:
            result = subprocess.run(full_command, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=True)
        if verbose:
            print("Command output: " + result.stdout.decode())
        return result.stdout
    except subprocess.CalledProcessError as e:
        if verbose:
            print("Command failed with return code " + str(e.returncode))
            print("Command output: " + e.stdout.decode())
            print("Command error: " + e.stderr.decode())
