import logging
import os
import yaml
import json

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    configs = {}
    errors = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as f:
                if filename.endswith('.json'):
                    config = json.load(f)
                elif filename.endswith(('.yaml', '.yml')):
                    config = yaml.safe_load(f)
                else:
                    # Try YAML as default
                    config = yaml.safe_load(f)

            # Apply overrides if provided
            if overrides:
                for key, value in overrides.items():
                    if key in config:
                        config[key] = value

            # Resolve environment variables if requested
            if resolve_env:
                config = _resolve_env_vars(config)

            configs[filename] = config
        except Exception as e:
            log_record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=__file__,
                lineno=0,
                msg=f"Error loading configuration file {filename}: {str(e)}",
                args=None,
                exc_info=None
            )
            errors.append(log_record)

    return configs, errors

def _resolve_env_vars(obj):
    """Recursively resolve environment variables in a configuration object."""
    if isinstance(obj, dict):
        return {key: _resolve_env_vars(value) for key, value in obj.items()}
    elif isinstance(obj, list):
        return [_resolve_env_vars(item) for item in obj]
    elif isinstance(obj, str):
        if obj.startswith('${') and obj.endswith('}'):
            env_var = obj[2:-1]
            return os.environ.get(env_var, obj)
        return obj
    else:
        return obj
